bio("zaynulabidin", [
 ("هُوَ عَلِيُّ بْنُ الْحُسَيْنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ، زَيْنُ الْعَابِدِينَ.", "Er ist ʿAli ibn al-Husayn ibn ʿAli ibn Abi Talib, genannt Zayn al-ʿAbidin (Zierde der Anbetenden).", 3539),
 ("كَانَ مَعَ أَبِيهِ الْحُسَيْنِ يَوْمَ كَرْبَلَاءَ، وَكَانَ مَرِيضًا فَلَمْ يُقَاتِلْ.", "Er war am Tag von Karbala bei seinem Vater al-Husayn, war aber krank und kämpfte nicht.", 3539),
 ("وَسُمِّيَ زَيْنَ الْعَابِدِينَ لِكَثْرَةِ عِبَادَتِهِ.", "Er wurde wegen seiner vielen Gottesdienste „Zierde der Anbetenden“ genannt.", 3545),
 ("كَانَ يَحْمِلُ الْخُبْزَ بِاللَّيْلِ عَلَى ظَهْرِهِ إِلَى الْمَسَاكِينِ.", "Nachts trug er Brot auf seinem Rücken zu den Armen.", 3546),
 ("وَكَانَ يَقُولُ: إِنَّ الصَّدَقَةَ فِي سَوَادِ اللَّيْلِ تُطْفِئُ غَضَبَ الرَّبِّ.", "Er sagte: Die Spende im Dunkel der Nacht löscht den Zorn des Herrn.", 3546),
 ("فَلَمَّا مَاتَ، فَقَدَ أُنَاسٌ فِي الْمَدِينَةِ مَا كَانَ يَأْتِيهِمْ بِاللَّيْلِ.", "Als er starb, merkten Leute in Medina, dass ausblieb, was ihnen nachts gebracht worden war.", 3546),
], [
 ("athar", "إِنَّ الصَّدَقَةَ فِي سَوَادِ اللَّيْلِ تُطْفِئُ غَضَبَ الرَّبِّ", "Die Spende im Dunkel der Nacht löscht den Zorn des Herrn. (Zayn al-ʿAbidin)", 3546, E),
 ("athar", "لَمَّا مَاتَ عَلِيُّ بنُ الحُسَيْنِ، وَجَدُوا بِظَهْرِهِ أَثَرًا مِمَّا كَانَ يَنْقُلُ الجُرْبَ بِاللَّيْلِ إِلَى مَنَازِلِ الأَرَامِلِ", "Als ʿAli ibn al-Husayn starb, fand man auf seinem Rücken Spuren der Säcke, die er nachts zu den Häusern der Witwen trug.", 3546, E),
])
bio("tawus", [
 ("هُوَ طَاوُوسُ بْنُ كَيْسَانَ، أَبُو عَبْدِ الرَّحْمَنِ، عَالِمُ الْيَمَنِ.", "Er ist Tawus ibn Kaysan, Abu ʿAbd ar-Rahman, der Gelehrte des Jemen.", 3810),
 ("كَانَ مِنْ أَبْنَاءِ الْفُرْسِ الَّذِينَ جَاؤُوا إِلَى الْيَمَنِ.", "Er stammte von den Persern ab, die in den Jemen gekommen waren.", 3810),
 ("وَكَانَ فَقِيهًا، قُدْوَةً فِي الْعِبَادَةِ وَالْخَوْفِ مِنَ اللَّهِ.", "Er war ein Rechtsgelehrter und ein Vorbild in Anbetung und Gottesfurcht.", 3810),
 ("وَكَانَ يَقُومُ يُصَلِّي بِاللَّيْلِ وَأَصْحَابُهُ نَائِمُونَ.", "Er stand nachts zum Gebet auf, während seine Gefährten schliefen.", 3812),
 ("تُوُفِّيَ بِمَكَّةَ سَنَةَ خَمْسٍ وَمِئَةٍ، وَقَدْ حَجَّ أَرْبَعِينَ حَجَّةً.", "Er starb im Jahr 105 in Mekka; er hatte vierzigmal den Haddsch vollzogen.", 3817),
], [
 ("athar", "الفَقِيْهُ، القُدْوَةُ، عَالِمُ اليَمَنِ", "Der Rechtsgelehrte, das Vorbild, der Gelehrte des Jemen. (adh-Dhahabi)", 3810),
 ("athar", "رَحِمَ اللهُ أَبَا عَبْدِ الرَّحْمَنِ، حَجَّ أَرْبَعِيْنَ حَجَّةً", "Allah erbarme sich Abu ʿAbd ar-Rahmans – er hat vierzigmal den Haddsch vollzogen.", 3817, E),
])
bio("sufyan-thawri", [
 ("هُوَ سُفْيَانُ بْنُ سَعِيدِ بْنِ مَسْرُوقٍ الثَّوْرِيُّ، أَبُو عَبْدِ اللَّهِ الْكُوفِيُّ.", "Er ist Sufyan ibn Saʿid ibn Masruq ath-Thawri, Abu ʿAbdillah aus Kufa.", 4894),
 ("وُلِدَ سَنَةَ سَبْعٍ وَتِسْعِينَ، وَطَلَبَ الْعِلْمَ صَغِيرًا بِعِنَايَةِ أَبِيهِ.", "Er wurde im Jahr 97 geboren und suchte schon als Junge Wissen, gefördert von seinem Vater.", 4894),
 ("لُقِّبَ بِشَيْخِ الْإِسْلَامِ، وَإِمَامِ الْحُفَّاظِ.", "Man nannte ihn Schaikh al-Islam und Imam der Hadith-Bewahrer.", 4894),
 ("قَالَ يَحْيَى الْقَطَّانُ: مَا رَأَيْتُ أَحَدًا أَحْفَظَ مِنْ سُفْيَانَ.", "Yahya al-Qattan sagte: Ich habe niemanden gesehen, der ein besseres Gedächtnis hatte als Sufyan.", 4901),
 ("وَكَانَ رَأْسًا فِي الزُّهْدِ وَالْخَوْفِ وَالْفِقْهِ، لَا يَخَافُ فِي اللَّهِ لَوْمَةَ لَائِمٍ.", "Er war führend im Weltverzicht, in der Gottesfurcht und im Fiqh und fürchtete um Allahs willen keinen Tadel.", 4905),
 ("طَلَبَهُ الْخَلِيفَةُ الْمَهْدِيُّ، فَتَوَارَى عَنْهُ.", "Der Kalif al-Mahdi suchte nach ihm, doch er hielt sich verborgen.", 4908),
 ("وَمَاتَ فِي أَوَّلِ سَنَةِ إِحْدَى وَسِتِّينَ وَمِئَةٍ.", "Er starb zu Beginn des Jahres 161.", 4943),
], [
 ("athar", "هُوَ شَيْخُ الإِسْلاَمِ، إِمَامُ الحُفَّاظِ، سَيِّدُ العُلَمَاءِ العَامِلِيْنَ فِي زَمَانِهِ", "Er ist Schaikh al-Islam, der Imam der Hadith-Bewahrer, der Herr der handelnden Gelehrten seiner Zeit. (adh-Dhahabi)", 4894),
 ("athar", "مَا رَأَيتُ أَحَدًا أَحْفَظَ مِنْ سُفْيَانَ، ثُمَّ شُعْبَةَ", "Ich habe niemanden mit besserem Gedächtnis gesehen als Sufyan, dann Schuʿba. (Yahya al-Qattan)", 4903, E),
], hinweis="Sufyan ath-Thawri zählt zu den Atbaʿ at-Tabiʿin (Generation nach den Tabiʿin). Nacherzählung und Zitate nach adh-Dhahabis Siyar.")
bio("sufyan-uyayna", [
 ("هُوَ سُفْيَانُ بْنُ عُيَيْنَةَ، أَبُو مُحَمَّدٍ الْهِلَالِيُّ، الْكُوفِيُّ ثُمَّ الْمَكِّيُّ.", "Er ist Sufyan ibn ʿUyayna, Abu Muhammad al-Hilali, aus Kufa, später in Mekka.", 5580),
 ("لُقِّبَ بِحَافِظِ الْعَصْرِ وَشَيْخِ الْإِسْلَامِ.", "Man nannte ihn den Hadith-Bewahrer seiner Zeit und Schaikh al-Islam.", 5580),
 ("وُلِدَ بِالْكُوفَةِ سَنَةَ سَبْعٍ وَمِئَةٍ.", "Er wurde im Jahr 107 in Kufa geboren.", 5581),
 ("ثُمَّ حُمِلَ إِلَى مَكَّةَ صَغِيرًا، فَسَمِعَ مِنْ عَمْرِو بْنِ دِينَارٍ.", "Als Kind wurde er nach Mekka gebracht und hörte dort ʿAmr ibn Dinar.", 5586),
 ("قَالَ الشَّافِعِيُّ: لَوْلَا مَالِكٌ وَسُفْيَانُ بْنُ عُيَيْنَةَ لَذَهَبَ عِلْمُ الْحِجَازِ.", "asch-Schafiʿi sagte: Gäbe es Malik und Sufyan ibn ʿUyayna nicht, wäre das Wissen des Hidschaz verloren gegangen.", 5583),
 ("وَمَاتَ سَنَةَ ثَمَانٍ وَتِسْعِينَ وَمِئَةٍ.", "Er starb im Jahr 198.", 5596),
], [
 ("athar", "لَوْلاَ مَالِكٌ وَسُفْيَانُ بنُ عُيَيْنَةَ، لَذَهَبَ عِلْمُ الحِجَازِ", "Gäbe es Malik und Sufyan ibn ʿUyayna nicht, wäre das Wissen des Hidschaz verloren gegangen. (asch-Schafiʿi)", 5583, E),
], hinweis="Sufyan ibn ʿUyayna zählt zu den Atbaʿ at-Tabiʿin. Nacherzählung und Zitate nach adh-Dhahabis Siyar.")
